import numpy as np
from sklearn.linear_model import LinearRegression

COLONNE = ["v", "f", "ap"]


def allena(df):
    X = np.log(df[COLONNE].to_numpy())
    return LinearRegression().fit(X, np.log(df["vita"].to_numpy()))


def esponenti(modello):
    return {c: float(k) for c, k in zip(COLONNE, modello.coef_)}


def vita_prevista(modello, v, f, ap):
    return float(np.exp(modello.predict(np.log([[v, f, ap]]))[0]))
